#!/usr/bin/env bash\n\nset -euo pipefail\n\n# Simple usage check\nif [[ $# -ne 1 ]]; then\n  echo "Usage: $0 /path/to/input.json" >&2\n  exit 1\nfi\n\nINPUT_FILE="$1"\n\n# Read max weight\nMAX_WEIGHT=$(jq '.max_weight' "$INPUT_FILE")\n\n# Extract items, compute value/weight ratio, sort descending\n# The output format per line: name weight value ratio\nITEMS=$(jq -r '.items[] | "\(.name) \(.weight) \(.value) \(.value/\(.weight))"' "$INPUT_FILE" |\n  sort -k4 -nr)\n\nSELECTED=()\nTOTAL_WEIGHT=0\nTOTAL_VALUE=0\n\nwhile read -r NAME WGT VAL RATIO; do\n  if (( TOTAL_WEIGHT + WGT <= MAX_WEIGHT )); then\n    SELECTED+=("$NAME")\n    TOTAL_WEIGHT=$(( TOTAL_WEIGHT + WGT ))\n    TOTAL_VALUE=$(( TOTAL_VALUE + VAL ))\n  fi\n# Stop early if we already hit the max weight\n  if (( TOTAL_WEIGHT == MAX_WEIGHT )); then\n    break\n  fi\n# Continue looping\n  true\n# The while loop reads from ITEMS via a here‑string\n  done <<< "$ITEMS"\n\n# Output results\nif [[ ${#SELECTED[@]} -eq 0 ]]; then\n  echo "No items fit within the weight limit of $MAX_WEIGHT."\n  exit 0\nfi\n\necho "Selected items:"\nfor ITEM in "${SELECTED[@]}"; do\n  # Retrieve weight and value for display\n  INFO=$(jq -r ".items[] | select(.name==\"$ITEM\") | \"- \(.name) (weight: \(.weight), value: \(.value))\"" "$INPUT_FILE")\n  echo "$INFO"\n done\n\necho "Total weight: $TOTAL_WEIGHT"\necho "Total value: $TOTAL_VALUE"\n
